import type { Metadata } from "next";
import { Assistant, Heebo, Bebas_Neue } from "next/font/google";
import { NextIntlClientProvider } from "next-intl";
import { getMessages } from "next-intl/server";
import { notFound } from "next/navigation";
import { routing } from "@/i18n/routing";
import Header from "@/components/layout/Header";
import "../globals.css";

const assistant = Assistant({
  subsets: ["latin", "hebrew"],
  weight: ["300", "400", "600", "700"],
  variable: "--font-assistant",
});

const heebo = Heebo({
  subsets: ["latin", "hebrew"],
  weight: ["400", "700", "800", "900"],
  variable: "--font-heebo",
});

const bebasNeue = Bebas_Neue({
  subsets: ["latin"],
  weight: ["400"],
  variable: "--font-bebas",
});

export const metadata: Metadata = {
  title: "מחיריסטה | Machirista",
  description: "השוואת מחירים בין כל רשתות הסופרמרקט בישראל",
};

export default async function LocaleLayout({
  children,
  params,
}: {
  children: React.ReactNode;
  params: Promise<{ locale: string }>;
}) {
  const { locale } = await params;

  if (!routing.locales.includes(locale as "he" | "en")) {
    notFound();
  }

  const messages = await getMessages();
  const isRtl = locale === "he";

  return (
    <html lang={locale} dir={isRtl ? "rtl" : "ltr"}>
      <body className={`${assistant.variable} ${heebo.variable} ${bebasNeue.variable} font-sans bg-ink-800 text-editorial-white antialiased`}>
        <NextIntlClientProvider messages={messages}>
          <div className="min-h-screen flex flex-col">
            <Header locale={locale} />
            <main className="flex-1">
              {children}
            </main>
            <footer className="border-t border-ink-600/60 py-10 mt-24">
              <div className="max-w-7xl mx-auto px-6 flex flex-col sm:flex-row items-center justify-between gap-3">
                <span className="font-display font-black text-editorial-white tracking-tight text-lg">
                  {isRtl ? "מחיריסטה" : "MACHIRISTA"}
                </span>
                <span className="text-sm text-editorial-muted">
                  © 2026 · {isRtl ? "נתונים מתעדכנים כל 3 שעות" : "Data refreshed every 3 hours"}
                </span>
              </div>
            </footer>
          </div>
        </NextIntlClientProvider>
      </body>
    </html>
  );
}
